CREATE DATABASE IF NOT EXISTS dbs_simobeat CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE dbs_simobeat;
CREATE TABLE IF NOT EXISTS users(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,nama VARCHAR(120) NOT NULL,email VARCHAR(190) NOT NULL UNIQUE,password VARCHAR(255) NOT NULL,role ENUM('admin','user') NOT NULL DEFAULT 'user',created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS motor(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,kode VARCHAR(20) NOT NULL UNIQUE,nama VARCHAR(120) NOT NULL,merek VARCHAR(100) NOT NULL DEFAULT 'Honda',tipe VARCHAR(100) NULL,tahun SMALLINT UNSIGNED NULL,deskripsi TEXT NULL) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS gejala(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,kode VARCHAR(20) NOT NULL UNIQUE,nama VARCHAR(180) NOT NULL,deskripsi TEXT NULL) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS kerusakan(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,kode VARCHAR(20) NOT NULL UNIQUE,nama VARCHAR(180) NOT NULL,deskripsi TEXT NULL,status ENUM('aktif','nonaktif') NOT NULL DEFAULT 'aktif') ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS solusi(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,kerusakan_id BIGINT UNSIGNED NOT NULL,deskripsi TEXT NOT NULL,FOREIGN KEY(kerusakan_id) REFERENCES kerusakan(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS aturan(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,kode VARCHAR(30) NOT NULL UNIQUE,kerusakan_id BIGINT UNSIGNED NOT NULL,status ENUM('aktif','nonaktif') NOT NULL DEFAULT 'aktif',FOREIGN KEY(kerusakan_id) REFERENCES kerusakan(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS aturan_detail(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,aturan_id BIGINT UNSIGNED NOT NULL,gejala_id BIGINT UNSIGNED NOT NULL,UNIQUE KEY uq_aturan_gejala(aturan_id,gejala_id),FOREIGN KEY(aturan_id) REFERENCES aturan(id) ON DELETE CASCADE,FOREIGN KEY(gejala_id) REFERENCES gejala(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS diagnosis(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,motor_id BIGINT UNSIGNED NOT NULL,kerusakan_id BIGINT UNSIGNED NULL,hasil VARCHAR(180) NOT NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,FOREIGN KEY(motor_id) REFERENCES motor(id),FOREIGN KEY(kerusakan_id) REFERENCES kerusakan(id) ON DELETE SET NULL) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS diagnosis_gejala(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,diagnosis_id BIGINT UNSIGNED NOT NULL,gejala_id BIGINT UNSIGNED NOT NULL,jawaban ENUM('YA','TIDAK') NOT NULL,UNIQUE KEY uq_diagnosis_gejala(diagnosis_id,gejala_id),FOREIGN KEY(diagnosis_id) REFERENCES diagnosis(id) ON DELETE CASCADE,FOREIGN KEY(gejala_id) REFERENCES gejala(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS log_aktivitas(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NULL,aktivitas VARCHAR(255) NOT NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE SET NULL) ENGINE=InnoDB;
